diff --git a/HTMLparser.c b/HTMLparser.c
index 3bebda6e2b21054c6ca3b5b4df52a6541f114ea7..b8b6bd230cff92f6010f7dd1a43bb103c405a926 100644
--- a/HTMLparser.c
+++ b/HTMLparser.c
@@ -411,7 +411,7 @@ htmlCurrentChar(xmlParserCtxtPtr ctxt, int *len) {
 	return(ctxt->token);
     }

-    if ((ctxt->input->end - ctxt->input->cur < 4) &&
+    if ((ctxt->input->end - ctxt->input->cur < INPUT_CHUNK) &&
         (xmlParserGrow(ctxt) < 0))
         return(0);

diff --git a/parserInternals.c b/parserInternals.c
index a06bb76abcc2967e3fdfe99917fc649c4fdcfc1c..52491505cb8ccf45d647704352d4b7923e5e29d8 100644
--- a/parserInternals.c
+++ b/parserInternals.c
@@ -527,7 +527,7 @@ xmlNextChar(xmlParserCtxtPtr ctxt)
 	return;
     }

-    if (ctxt->input->end - ctxt->input->cur < 4) {
+    if (ctxt->input->end - ctxt->input->cur < INPUT_CHUNK) {
         if (xmlParserGrow(ctxt) < 0)
             return;
         if (ctxt->input->cur >= ctxt->input->end)
@@ -674,7 +674,7 @@ xmlCurrentChar(xmlParserCtxtPtr ctxt, int *len) {
     if (ctxt->instate == XML_PARSER_EOF)
 	return(0);

-    if ((ctxt->input->end - ctxt->input->cur < 4) &&
+    if ((ctxt->input->end - ctxt->input->cur < INPUT_CHUNK) &&
         (xmlParserGrow(ctxt) < 0))
         return(0);
